      backup_text =
        "# Crop Plotter #\n\n\
         # Plant a 3x3 grove: pick a seed, then plant cells, rows, or columns. #\n\
         # Nested mapi over a list of lists; OnClick plants and OnDoubleClick \
         uproots. #\n\n\
         type Plant = String in\n\
         type Grove = [[Plant]] in\n\
         type Row = Int in\n\
         type Col = Int in\n\n\
         type Model = (\n\
         grove = Grove,\n\
         currentSeed = Plant,\n\
         seedInventory = [Plant]\n\
         ) in\n\n\
         type Action =\n\
         + SelectSeed(Int)\n\
         + PlantSeed(Row, Col)\n\
         + Uproot(Row, Col)\n\
         + ClearGrove\n\
         + PlantRow(Row)\n\
         + PlantCol(Col)\n\
         in\n\n\
         let init: Model = (\n\
         grove = [\n\
         [\"\", \"\", \"\"],\n\
         [\"\", \"\", \"\"],\n\
         [\"\", \"\", \"\"]\n\
         ],\n\
         currentSeed = \"\240\159\140\177\",\n\
         seedInventory = [\"\240\159\140\177\", \"\240\159\140\191\", \
         \"\240\159\141\132\", \"\226\152\152\239\184\143\", \
         \"\240\159\140\184\"]\n\
         ) in\n\n\
         let setCell(grove: Grove, row: Row, col: Col, plant: Plant): Grove =\n\
         mapi(grove, fun (i, r) ->\n\
         if i == row\n\
         then mapi(r, fun (j, c) -> if j == col then plant else c)\n\
         else r)\n\
         in\n\n\
         let setRow(grove: Grove, targetRow: Row, plant: Plant): Grove =\n\
         mapi(grove, fun (i, row) ->\n\
         if i == targetRow\n\
         then map(row, fun _ -> plant)\n\
         else row)\n\
         in\n\n\
         let setCol(grove: Grove, col: Col, plant: Plant): Grove =\n\
         map(grove, fun row ->\n\
         mapi(row, fun (j, c) -> if j == col then plant else c))\n\
         in\n\n\
         let setAll(grove: Grove, plant: Plant): Grove =\n\
         map(grove, fun row -> map(row, fun _ -> plant))\n\
         in\n\n\
         let updateGrove(model: Model, f: Grove -> Grove): Model =\n\
         (\n\
         grove = f(model.grove),\n\
         currentSeed = model.currentSeed,\n\
         seedInventory = model.seedInventory\n\
         )\n\
         in\n\n\
         let update(model: Model, action: Action): Model =\n\
         case action\n\
         | SelectSeed(idx) =>\n\
         (\n\
         grove = model.grove,\n\
         currentSeed = nth(model.seedInventory, idx),\n\
         seedInventory = model.seedInventory\n\
         )\n\
         | PlantSeed(row, col) =>\n\
         updateGrove(model, fun g -> setCell(g, row, col, model.currentSeed))\n\
         | Uproot(row, col) =>\n\
         updateGrove(model, fun g -> setCell(g, row, col, \"\"))\n\
         | ClearGrove =>\n\
         updateGrove(model, fun g -> setAll(g, \"\"))\n\
         | PlantRow(row) =>\n\
         updateGrove(model, fun g -> setRow(g, row, model.currentSeed))\n\
         | PlantCol(col) =>\n\
         updateGrove(model, fun g -> setCol(g, col, model.currentSeed))\n\
         end\n\
         in\n\n\
         # ===== VIEW ===== #\n\n\
         let stripBtn(label: String, action: Action): HTML =\n\
         Button(\n\
         [\n\
         OnClick(action),\n\
         Style([\n\
         (\"width\", \"56px\"), (\"height\", \"20px\"), (\"font-size\", \
         \"0.75em\"),\n\
         (\"background\", \"var(--T1)\"), (\"color\", \"var(--BR3)\"),\n\
         (\"border\", \"1px solid var(--BR1)\"), (\"border-radius\", \"3px\"),\n\
         (\"font-family\", \"inherit\"), (\"cursor\", \"pointer\")\n\
         ])\n\
         ],\n\
         [Text(label)]\n\
         )\n\
         in\n\n\
         let view(model: Model): HTML =\n\
         Div(\n\
         [Style([\n\
         (\"max-width\", \"320px\"), (\"margin\", \"0 auto\"), \
         (\"text-align\", \"center\"),\n\
         (\"font-family\", \"var(--code-font)\"), (\"font-size\", \"0.85em\"),\n\
         (\"background\", \"var(--SAND)\"), (\"color\", \"var(--STONE)\"),\n\
         (\"border\", \"1px solid var(--BR1)\"), (\"border-radius\", \"0.4em\"),\n\
         (\"overflow\", \"hidden\")\n\
         ])],\n\
         [\n\
         Div(\n\
         [Style([(\"padding\", \"0.9em 1em 0.8em\")])],\n\
         [\n\
         Div([Style([(\"font-size\", \"1.2em\"), (\"font-weight\", \"bold\"), \
         (\"color\", \"var(--BR4)\")])],\n\
         [Text(\"\240\159\140\153 Crop Plotter\")]),\n\
         Div([Style([(\"font-size\", \"0.75em\"), (\"color\", \"var(--BR3)\"), \
         (\"margin-top\", \"0.3em\")])],\n\
         [Text(\"Click to plant, double-click to uproot\")])\n\
         ]\n\
         ),\n\
         # Seed inventory: the held seed is marked by border colour, not \
         width, #\n\
         # so selecting one never shifts the row #\n\
         Div(\n\
         [Style([(\"display\", \"flex\"), (\"justify-content\", \"center\"), \
         (\"gap\", \"0.4em\"),\n\
         (\"padding\", \"0.7em 1em\"), (\"background\", \"var(--T2)\"),\n\
         (\"border-top\", \"1px solid var(--BR1)\"),\n\
         (\"border-bottom\", \"1px solid var(--BR1)\")])],\n\
         mapi(model.seedInventory, fun (idx, seed) ->\n\
         Button(\n\
         [\n\
         OnClick(SelectSeed(idx)),\n\
         Style([\n\
         (\"font-size\", \"1.2em\"), (\"padding\", \"0.2em 0.4em\"), \
         (\"cursor\", \"pointer\"),\n\
         (\"font-family\", \"inherit\"), (\"border-radius\", \"3px\"),\n\
         (\"background\", if seed == model.currentSeed then \"var(--SAND)\" \
         else \"var(--T1)\"),\n\
         (\"border\", if seed == model.currentSeed\n\
         then \"1px solid var(--G0)\"\n\
         else \"1px solid var(--BR1)\")\n\
         ])\n\
         ],\n\
         [Text(seed)]\n\
         )\n\
         )\n\
         ),\n\
         Div(\n\
         [Style([(\"padding\", \"0.7em 1em\")])],\n\
         [\n\
         # Column planting strip, offset past the row-button column #\n\
         Div(\n\
         [Style([(\"display\", \"flex\"), (\"justify-content\", \"center\"), \
         (\"gap\", \"2px\"),\n\
         (\"margin-left\", \"58px\")])],\n\
         mapi(nth(model.grove, 0), fun (col_idx, _cell) ->\n\
         stripBtn(\"\226\134\147 col\", PlantCol(col_idx))\n\
         )\n\
         ),\n\
         # Grove grid, each row prefixed by its row-planting button #\n\
         Div(\n\
         [Style([(\"display\", \"inline-block\"), (\"margin-top\", \"2px\")])],\n\
         mapi(model.grove, fun (row_idx, row) ->\n\
         Div(\n\
         [Style([(\"display\", \"flex\"), (\"justify-content\", \"center\"), \
         (\"gap\", \"2px\"),\n\
         (\"margin-bottom\", \"2px\")])],\n\
         [stripBtn(\"\226\134\146 row\", PlantRow(row_idx))] @\n\
         mapi(row, fun (col_idx, cell) ->\n\
         Button(\n\
         [\n\
         OnClick(PlantSeed(row_idx, col_idx)),\n\
         OnDoubleClick(Uproot(row_idx, col_idx)),\n\
         Style([\n\
         (\"width\", \"56px\"), (\"height\", \"56px\"), (\"font-size\", \
         \"1.5em\"),\n\
         (\"background\", \"var(--T1)\"), (\"border\", \"1px solid \
         var(--BR1)\"),\n\
         (\"border-radius\", \"3px\"), (\"font-family\", \"inherit\"),\n\
         (\"cursor\", \"pointer\")\n\
         ])\n\
         ],\n\
         [Text(if cell == \"\" then \" \" else cell)]\n\
         )\n\
         )\n\
         )\n\
         )\n\
         ),\n\
         Button(\n\
         [\n\
         OnClick(ClearGrove),\n\
         Style([(\"width\", \"100%\"), (\"margin-top\", \"0.5em\"), \
         (\"padding\", \"0.4em\"),\n\
         (\"background\", \"var(--T1)\"), (\"color\", \"var(--STONE)\"),\n\
         (\"border\", \"1px solid var(--BR1)\"), (\"border-radius\", \"3px\"),\n\
         (\"cursor\", \"pointer\"), (\"font-family\", \"inherit\"),\n\
         (\"font-size\", \"0.85em\")])\n\
         ],\n\
         [Text(\"\240\159\140\190 Clear Grove\")]\n\
         )\n\
         ]\n\
         ),\n\
         Div(\n\
         [Style([(\"padding\", \"0.6em 1em\"), (\"font-size\", \"0.75em\"), \
         (\"color\", \"var(--BR3)\"),\n\
         (\"border-top\", \"1px solid var(--BR1)\")])],\n\
         [Text(\"Holding \" ++ model.currentSeed)]\n\
         )\n\
         ]\n\
         )\n\
         in\n\n\
         let subs(_model: Model): Sub = SubNone in\n\n\
         # ===== TESTS ===== #\n\n\
         # With (model, action) order, `update` already has fold_left's shape #\n\
         let run(model: Model, actions: [Action]): Model =\n\
         fold_left(actions, update, model)\n\
         in\n\n\
         hint \"planting a single cell\"\n\
         test\n\
         update(init, PlantSeed(0, 0)).grove\n\
         == [[\"\240\159\140\177\", \"\", \"\"], [\"\", \"\", \"\"], [\"\", \
         \"\", \"\"]]\n\
         end;\n\n\
         hint \"row and column planting cross\"\n\
         test\n\
         let m = run(init, [PlantRow(0), PlantCol(1)]) in\n\
         m.grove == [[\"\240\159\140\177\", \"\240\159\140\177\", \
         \"\240\159\140\177\"], [\"\", \"\240\159\140\177\", \"\"], [\"\", \
         \"\240\159\140\177\", \"\"]]\n\
         end;\n\n\
         hint \"planting uses the selected seed, uprooting clears a cell\"\n\
         test\n\
         let m = run(init, [SelectSeed(2), PlantRow(0), Uproot(0, 1)]) in\n\
         m.grove == [[\"\240\159\141\132\", \"\", \"\240\159\141\132\"], \
         [\"\", \"\", \"\"], [\"\", \"\", \"\"]]\n\
         && m.currentSeed == \"\240\159\141\132\"\n\
         end;\n\n\
         hint \"clearing the grove empties every cell\"\n\
         test\n\
         let m = run(init, [PlantCol(1), ClearGrove]) in\n\
         m.grove == [[\"\", \"\", \"\"], [\"\", \"\", \"\"], [\"\", \"\", \"\"]]\n\
         end;\n\n\
         # Nothing here issues a command, so `update` returns a bare Model and \
         is #\n\
         # lifted into the (Model, Cmd) shape the app tuple expects. #\n\n\
         let noCmd(f: (Model, Action) -> Model): (Model, Action) -> (Model, \
         Cmd) =\n\
         fun (model, action) -> (f(model, action), CmdNone)\n\
         in\n\n\
         ^^html((init, noCmd(update), view, subs))\n";
      refractors = "()";
    } )
